// ***************
// Filename: pcie_tl_ep_top.sv
// Author: FPGA Cores 4 U
// Description: pcie_tl_ep with its AXI4-Lite register interface, the block
//   designs and testbenches instantiate: the register map pcie_tl_ep_regs
//   (u_regs, src/include/pcie_tl_ep_regs.sv, ID "PCIE", VERSION and DATE at
//   0x00-0x08, the registers from 0x10) and the logic pcie_tl_ep (u_core,
//   src/pcie_tl_ep.sv), joined by their register ports (cfg_* to the logic,
//   sts_* back). Generated by ip/scripts/regmap_gen.py from
//   pcie_tl_ep_regs.json and the ports of pcie_tl_ep: regenerate after
//   changing either. Clock - aclk. Reset - synchronous active low aresetn.
// Date: 2026-10-12
module pcie_tl_ep_top #(
  parameter logic [15:0] VENDOR_ID = 16'h1234,
  parameter logic [15:0] DEVICE_ID = 16'h5678,
  parameter int BAR_BITS = 13,
  parameter int RAM_DW = 1024,
  parameter int FIFO_DEPTH = 512
) (
  input  logic        aclk,
  input  logic        aresetn,
  input  logic [7:0]  s_axil_awaddr,
  input  logic        s_axil_awvalid,
  output logic        s_axil_awready,
  input  logic [31:0] s_axil_wdata,
  input  logic [3:0]  s_axil_wstrb,
  input  logic        s_axil_wvalid,
  output logic        s_axil_wready,
  output logic [1:0]  s_axil_bresp,
  output logic        s_axil_bvalid,
  input  logic        s_axil_bready,
  input  logic [7:0]  s_axil_araddr,
  input  logic        s_axil_arvalid,
  output logic        s_axil_arready,
  output logic [31:0] s_axil_rdata,
  output logic [1:0]  s_axil_rresp,
  output logic        s_axil_rvalid,
  input  logic        s_axil_rready,
  input  logic [63:0] rx_axis_tdata,
  input  logic [7:0]  rx_axis_tkeep,
  input  logic        rx_axis_tlast,
  input  logic        rx_axis_tvalid,
  output logic        rx_axis_tready,
  output logic [63:0] tx_axis_tdata,
  output logic [7:0]  tx_axis_tkeep,
  output logic        tx_axis_tlast,
  output logic        tx_axis_tvalid,
  input  logic        tx_axis_tready,
  input  logic [31:0] s_axis_tdata,
  input  logic        s_axis_tvalid,
  output logic        s_axis_tready,
  input  logic        s_axis_tlast,
  output logic [31:0] m_axis_tdata,
  output logic        m_axis_tvalid,
  input  logic        m_axis_tready,
  output logic        m_axis_tlast
);
  // register ports between the register map and the logic
  logic cfg_ctrl;
  logic [31:0] cfg_dma_addr_lo;
  logic cfg_dma_addr_lo_wr;
  logic [31:0] cfg_dma_addr_hi;
  logic cfg_dma_addr_hi_wr;
  logic [9:0] cfg_dma_len_dw;
  logic [31:0] sts_status;
  logic [15:0] sts_cpl_id;
  logic [31:0] sts_bar0;
  logic [31:0] sts_rx_tlp;
  logic [31:0] sts_mwr;
  logic [31:0] sts_mrd;
  logic [31:0] sts_cfg;
  logic [31:0] sts_ur;
  logic [31:0] sts_dma_tlp;

  pcie_tl_ep_regs u_regs (
    .aclk,
    .aresetn,
    .s_axil_awaddr,
    .s_axil_awvalid,
    .s_axil_awready,
    .s_axil_wdata,
    .s_axil_wstrb,
    .s_axil_wvalid,
    .s_axil_wready,
    .s_axil_bresp,
    .s_axil_bvalid,
    .s_axil_bready,
    .s_axil_araddr,
    .s_axil_arvalid,
    .s_axil_arready,
    .s_axil_rdata,
    .s_axil_rresp,
    .s_axil_rvalid,
    .s_axil_rready,
    .ctrl_o(cfg_ctrl),
    .ctrl_wr_o(),
    .dma_addr_lo_o(cfg_dma_addr_lo),
    .dma_addr_lo_wr_o(cfg_dma_addr_lo_wr),
    .dma_addr_hi_o(cfg_dma_addr_hi),
    .dma_addr_hi_wr_o(cfg_dma_addr_hi_wr),
    .dma_len_dw_o(cfg_dma_len_dw),
    .dma_len_dw_wr_o(),
    .status_i(sts_status),
    .cpl_id_i(sts_cpl_id),
    .bar0_i(sts_bar0),
    .rx_tlp_i(sts_rx_tlp),
    .mwr_i(sts_mwr),
    .mrd_i(sts_mrd),
    .cfg_i(sts_cfg),
    .ur_i(sts_ur),
    .dma_tlp_i(sts_dma_tlp)
  );
  pcie_tl_ep #(
    .VENDOR_ID(VENDOR_ID),
    .DEVICE_ID(DEVICE_ID),
    .BAR_BITS(BAR_BITS),
    .RAM_DW(RAM_DW),
    .FIFO_DEPTH(FIFO_DEPTH)
  ) u_core (
    .aclk,
    .aresetn,
    .rx_axis_tdata,
    .rx_axis_tkeep,
    .rx_axis_tlast,
    .rx_axis_tvalid,
    .rx_axis_tready,
    .tx_axis_tdata,
    .tx_axis_tkeep,
    .tx_axis_tlast,
    .tx_axis_tvalid,
    .tx_axis_tready,
    .s_axis_tdata,
    .s_axis_tvalid,
    .s_axis_tready,
    .s_axis_tlast,
    .m_axis_tdata,
    .m_axis_tvalid,
    .m_axis_tready,
    .m_axis_tlast,
    .cfg_ctrl,
    .cfg_dma_addr_lo,
    .cfg_dma_addr_lo_wr,
    .cfg_dma_addr_hi,
    .cfg_dma_addr_hi_wr,
    .cfg_dma_len_dw,
    .sts_status,
    .sts_cpl_id,
    .sts_bar0,
    .sts_rx_tlp,
    .sts_mwr,
    .sts_mrd,
    .sts_cfg,
    .sts_ur,
    .sts_dma_tlp
  );
endmodule
